// routes/homeRoutes.js
import express from "express";
import multer from "multer";
import path from "path";
import HomeContent from "../models/HomeContent.js";
import { saveHomeData } from "../controllers/adminHomeController.js";

const router = express.Router();

// ✅ Multer setup
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, "uploads/home"),
  filename: (req, file, cb) => cb(null, Date.now() + path.extname(file.originalname)),
});
const upload = multer({ storage });

// ✅ Visitor-side GET route
router.get("/", async (req, res) => {
  try {
    const content = await HomeContent.findOne();
    res.json(
      content || {
        bannerVideos: [],
        welcomeText: "",
        activities: [],
        testimonialVideos: [],
      }
    );
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ✅ Admin save route (for uploads or data)
router.post("/", upload.single("file"), saveHomeData);

export default router;
